<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/report_error.php';
try{$uid=(int)requireAuth()->id;$id=(int)($_GET['id']??0);$c=db();requirePermission($c,$uid,'reports.view');if($id>0){$s=$c->prepare('SELECT * FROM erp_filing_archives WHERE id=? AND user_id=?');$s->bind_param('ii',$id,$uid);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();if(!$row)throw new OutOfBoundsException('Filing archive not found');$row['source']=json_decode($row['source_json'],true);$row['result']=json_decode($row['result_json'],true);unset($row['source_json'],$row['result_json']);jsonResponse(['success'=>true,'data'=>$row]);}$s=$c->prepare('SELECT id,declaration_type,source_entity_id,filing_sequence,period_start,period_end,report_version,source_sha256,result_sha256,archive_sha256,source_row_count,captured_by,captured_at FROM erp_filing_archives WHERE user_id=? ORDER BY period_end DESC,id DESC');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();jsonResponse(['success'=>true,'data'=>$rows]);}catch(Throwable $e){reportFailureResponse($e,'Could not load the filing archives.','FILING_ARCHIVE_LOAD_FAILED');}
